steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(filter: {
        priority: { eq: 3 },
        dueDate: { eq: \"2026-12-02\" }
      }, first: 10) {
        nodes {
          id
          identifier
          title
          description
          priority
          dueDate
          labels {
            nodes {
              name
            }
          }
          milestone {
            name
          }
        }
      }
    }"
  }'
